CREATE OR REPLACE FUNCTION public.fn_get_material_shipment_by_order_id(p_order_id uuid)  RETURNS TABLE(id uuid, order_id uuid, shipment_number character varying, carrier_name character varying, tracking_reference character varying, dispatch_date timestamp with time zone, estimated_delivery_date timestamp with time zone, actual_delivery_date timestamp with time zone, delivery_status character varying, proof_of_delivery_notes text, recorded_by_user_id uuid, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          id, order_id, shipment_number, carrier_name, tracking_reference,         dispatch_date, estimated_delivery_date, actual_delivery_date,         delivery_status, proof_of_delivery_notes, recorded_by_user_id,         created_at, updated_at     FROM material_shipments      WHERE order_id = p_order_id      ORDER BY created_at DESC      LIMIT 1; $function$ ;
